// Usage: node pixdiff.mjs <dirA> <dirB> <relative png>... ; prints how many pixels differ per file.
import { createRequire } from "node:module";
import { join } from "node:path";

const require = createRequire(join(process.cwd(), "package.json"));
const sharp = require("sharp");
const [dirA, dirB, ...files] = process.argv.slice(2);

for (const file of files) {
  const [a, b] = await Promise.all(
    [dirA, dirB].map((dir) => sharp(join(dir, file)).ensureAlpha().raw().toBuffer({ resolveWithObject: true })),
  );
  if (a.info.width !== b.info.width || a.info.height !== b.info.height) {
    console.info(file, "size", `${a.info.width}x${a.info.height}`, "vs", `${b.info.width}x${b.info.height}`);
    continue;
  }
  let differing = 0;
  for (let i = 0; i < a.data.length; i += 4) {
    if (a.data[i] !== b.data[i] || a.data[i + 1] !== b.data[i + 1] || a.data[i + 2] !== b.data[i + 2]) differing += 1;
  }
  console.info(file, "differing pixels", differing, "of", a.data.length / 4);
}

