import { renderHook, waitFor } from "@testing-library/react";
import { HttpResponse, delay, http } from "msw";
import { describe, expect, it, vi } from "vitest";
import { searchMatches, tasks } from "../../test/fixtures.ts";
import { queryWrapper } from "../../test/query-wrapper.tsx";
import { server } from "../../test/server.ts";
import { useTasks } from "./tasks.ts";

const lateMs = 60;
const abResults = tasks.slice(0, 3);

// "ab" answers late, after "abc" has already answered.
const searchWithLateAb = (onAbAborted: () => void = () => undefined) =>
  http.get("/api/v1/tasks", async ({ request }) => {
    if (new URL(request.url).searchParams.get("q") !== "ab")
      return HttpResponse.json({ items: searchMatches });
    request.signal.addEventListener("abort", onAbAborted);
    await delay(lateMs);
    return HttpResponse.json({ items: abResults });
  });

describe("useTasks", () => {
  it("keeps abc on screen when the late ab response arrives", async () => {
    server.use(searchWithLateAb());
    const { wrapper } = queryWrapper();
    const { result, rerender } = renderHook(({ q }) => useTasks(q), {
      wrapper,
      initialProps: { q: "ab" },
    });

    rerender({ q: "abc" });
    await waitFor(() => {
      expect(result.current.data).toEqual(searchMatches);
    });
    await delay(lateMs * 2);

    expect(result.current.data).toEqual(searchMatches);
  });

  it("aborts the superseded search request", async () => {
    const aborted = vi.fn<() => void>();
    server.use(searchWithLateAb(aborted));
    const { wrapper } = queryWrapper();
    const { rerender } = renderHook(({ q }) => useTasks(q), { wrapper, initialProps: { q: "ab" } });

    rerender({ q: "abc" });

    await waitFor(() => {
      expect(aborted).toHaveBeenCalledOnce();
    });
  });
});

