        forgetTask(client, taskId);
        return;
      }
      if (!snapshot) return;
      restoreLists(client, snapshot.lists);
      client.setQueryData(taskKeys.detail(taskId), snapshot.detail);
    },
    onSettled: () => client.invalidateQueries({ queryKey: taskKeys.lists() }),
  });
};

