import { describe, expect, it } from "vitest";
import { makeTask } from "../../test/fixtures.ts";
import { moveAfter } from "./order.ts";

const [first, second, third] = ["1", "2", "3"].map((n) =>
  makeTask({ id: `00000000-0000-4000-8000-00000000000${n}`, title: `Task ${n}` }),
);

const titles = (items: readonly { readonly title: string }[]) => items.map((task) => task.title);

describe("moveAfter", () => {
  it("moves a task after another without mutating the input", () => {
    const items = Object.freeze([first, second, third].filter((task) => task !== undefined));

    const moved = moveAfter(items, items[0]?.id ?? "", items[2]?.id ?? null);

    expect(titles(moved)).toEqual(["Task 2", "Task 3", "Task 1"]);
    expect(titles(items)).toEqual(["Task 1", "Task 2", "Task 3"]);
  });

  it("moves a task to the top", () => {
    const items = [first, second, third].filter((task) => task !== undefined);

    expect(titles(moveAfter(items, items[2]?.id ?? "", null))).toEqual([
      "Task 3",
      "Task 1",
      "Task 2",
    ]);
  });
});

