const noticeKinds: Readonly<Record<string, NoticeKind>> = {
  [taskKeys.mutations.toggle[1]]: "toggle",
};

const failedTo: Readonly<Record<NoticeKind, string>> = {
  toggle: "Couldn't update the task, so it's back as it was.",
};

