1	import { type ReactNode, createContext, use } from "react";
2	import { useMe, useSignIn, useSignOut, useSignUp } from "../query/auth.ts";
3	import type { User } from "../schema/auth.ts";
4	
5	/** Whether anyone is signed in: still checking, a visitor, or a user. */
6	export type Session =
7	  | { readonly status: "loading"; readonly user: null }
8	  | { readonly status: "signed-out"; readonly user: null }
9	  | { readonly status: "signed-in"; readonly user: User };
10	
11	/** The session, and the actions that change it. */
12	export type Auth = Session & {
13	  readonly signIn: ReturnType<typeof useSignIn>;
14	  readonly signUp: ReturnType<typeof useSignUp>;
15	  readonly signOut: ReturnType<typeof useSignOut>;
16	};
17	
18	const AuthContext = createContext<Auth | null>(null);
19	
20	/** Read the session from the cached `me` answer: undefined while checking, null for a visitor. */
21	export const sessionFrom = (me: User | null | undefined): Session => {
22	  if (me === undefined) return { status: "loading", user: null };
23	  if (me === null) return { status: "signed-out", user: null };
24	  return { status: "signed-in", user: me };
25	};
26	
27	/** Gives every page below it the session, worked out from the server's answer on each render rather than copied. */
28	export function AuthProvider({ children }: { readonly children: ReactNode }) {
29	  const me = useMe();
30	  const signIn = useSignIn();
31	  const signUp = useSignUp();
32	  const signOut = useSignOut();
33	  return (
34	    <AuthContext value={{ ...sessionFrom(me.data), signIn, signUp, signOut }}>
35	      {children}
36	    </AuthContext>
37	  );
38	}
39	
40	/** The session and its actions; only valid below `AuthProvider`. */
