function AppRoot() {
  const navigate = useNavigate();
  return (
    <AuthProvider>
      <NavigationProvider
        navigate={(href) => {
          void navigate(href);
        }}
      >
        <Outlet />
      </NavigationProvider>
    </AuthProvider>
  );
}

/** The app's route table. */
export const appRoutes: RouteObject[] = [
  {
    element: <AppRoot />,
