1	import {
2	  type MutationKey,
3	  type QueryClient,
4	  type QueryKey,
5	  keepPreviousData,
6	  skipToken,
7	  useMutation,
8	  useMutationState,
9	  useQuery,
10	  useQueryClient,
11	} from "@tanstack/react-query";
12	import { useState } from "react";
13	import { type ApiError, ApiErrorCode } from "../api/client.ts";
14	import { createTask, deleteTask, getTask, listTasks, moveTask, updateTask } from "../api/tasks.ts";
15	import type { Task } from "../schema/task.ts";
16	import type { TaskChanges } from "../task-draft.ts";
17	import { moveAfter } from "../tasks/order.ts";
18	import { taskKeys } from "./keys.ts";
19	
20	/**
21	 * The user's tasks, or the matches for `q`. Each term is cached on its own, so a late answer for an older term never
22	 * replaces a newer one; the previous results stay on screen while the next load; and a superseded request is
23	 * aborted ([query cancellation](https://tanstack.com/query/v5/docs/framework/react/guides/query-cancellation)).
24	 */
25	export const useTasks = (q: string) =>
26	  useQuery({
27	    queryKey: taskKeys.list(q),
28	    queryFn: ({ signal }) => listTasks(q, signal),
29	    placeholderData: keepPreviousData,
30	  });
31	
32	/**
33	 * One task, or nothing to fetch when `taskId` is null. A 404 (missing, or someone else's) is an answer the page shows;
34	 * any other failure goes to the route error boundary.
35	 */
36	export const useTask = (taskId: string | null) =>
37	  useQuery({
38	    queryKey: taskKeys.detail(taskId ?? ""),
39	    queryFn: taskId === null ? skipToken : ({ signal }) => getTask(taskId, signal),
40	    throwOnError: (error) => !isNotFound(error),
41	  });
42	
43	/** A save from the detail screen: the changed fields, and the version the edit started from. */
44	export interface UpdateVariables {
45	  readonly taskId: string;
46	  readonly changes: TaskChanges;
47	  readonly version: number;
48	}
49	
50	/**
51	 * Save a task's edited fields with `If-Match`, so a save made against an older version is refused (412) rather than
52	 * overwriting someone else's change. A 412 reloads the task, so the screen can show what changed.
53	 */
54	export const useUpdateTask = () => {
55	  const client = useQueryClient();
56	  return useMutation({
57	    mutationKey: taskKeys.mutations.update,
58	    mutationFn: ({ taskId, changes, version }: UpdateVariables) =>
59	      updateTask(taskId, changes, version),
60	    onSuccess: (task) => {
61	      client.setQueryData(taskKeys.detail(task.id), task);
62	      void client.invalidateQueries({ queryKey: taskKeys.lists() });
63	    },
64	    onError: (error, { taskId }) => {
65	      if (error.code === ApiErrorCode.VersionMismatch)
66	        void client.invalidateQueries({ queryKey: taskKeys.detail(taskId) });
67	    },
68	  });
69	};
70	
71	/** Every cached task list as it was before an optimistic change, to put back if the change fails. */
72	export type ListSnapshot = readonly (readonly [QueryKey, readonly Task[] | undefined])[];
73	
74	/**
75	 * Build the first step of an optimistic change from a pure list transform: stop list fetches that would overwrite it,
76	 * keep a snapshot, apply `apply` to every cached list, and hand back the snapshot for a rollback.
77	 */
78	export const optimisticListUpdate =
79	  <V>(client: QueryClient, apply: (items: readonly Task[], vars: V) => readonly Task[]) =>
80	  async (vars: V): Promise<ListSnapshot> => {
81	    await client.cancelQueries({ queryKey: taskKeys.lists() });
82	    const snapshot = client.getQueriesData<readonly Task[]>({ queryKey: taskKeys.lists() });
83	    client.setQueriesData<readonly Task[]>(
84	      { queryKey: taskKeys.lists() },
85	      (items) => items && apply(items, vars),
86	    );
87	    return snapshot;
88	  };
89	
